function treatmentSource(url, label) {
  return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
}

function renderRegimen(protocol) {
  return `<article class="notice treatment-regimen" style="margin:10px 0">
    <p><strong>${esc(protocol.regimen)}</strong></p>
    <p><b>Препараты и дозы</b></p>
    <ul>${protocol.drugs.map(drug => `<li>${esc(drug)}</li>`).join('')}</ul>
    <p><b>Интервал и длительность.</b> ${esc(protocol.cycle)}</p>
    <p><b>Условия применения.</b> ${esc(protocol.notes)}</p>
    <p class="fine">${treatmentSource(protocol.url, 'Источник схемы')}${protocol.reference ? ` · ${treatmentSource(protocol.reference[1], protocol.reference[0])}` : ''}</p>
  </article>`;
}

function stageExtras(c) {
  const stage = state.stage;
  const treatment = LUNG_TREATMENT[c.id]?.[stage];
  const drugsSelected = state.treatmentTab === 'drugs';
  const existingProtocol = STAGE_PROTOCOLS[c.id]?.[stage];
  const regimens = treatment?.regimens ?? (existingProtocol ? [existingProtocol] : []);
  const legacySurgery = stage !== 'IV' || ['c005', 'c022', 'c024'].includes(c.id);
  const surgery = treatment?.surgery ?? (legacySurgery ? SURGERY_DETAILS[c.id] : undefined);
  const intro = treatment?.intro;
  const drugContent = regimens.length
    ? `<p class="fine">Опубликованные режимы для клинической сверки. Применимость и регистрация зависят от показания и страны.</p>
       ${intro ? `<p>${esc(intro[0])} ${treatmentSource(intro[1], 'Источник')}</p>` : ''}
       ${regimens.map(renderRegimen).join('')}`
    : `<div class="notice" style="margin:10px 0">Для этой стадии пока нет проверенного дозового протокола. Режим, дозы и длительность будут добавлены после сверки с первоисточником.</div>`;
  const surgeryContent = `<div class="notice" style="margin:10px 0">
    ${surgery ? `<p><b>Возможный объём.</b> ${esc(surgery.procedure)}</p>
      <p><b>Ограничения и противопоказания.</b> ${esc(surgery.limits)}</p>` : `<p>Для этой стадии нет универсального хирургического стандарта в текущей редакции карточки. Решение о вмешательстве зависит от нозологии, резектабельности, цели лечения и консилиума.</p>`}
    <p class="fine">Оценка операбельности индивидуальна. В карточке приведены типовые ограничения.${surgery?.url ? ` ${treatmentSource(surgery.url, 'Источник хирургической тактики')}` : ''}</p>
  </div>`;
  return `<div class="stage-extras">
    <div class="tabs" style="margin:14px 0 10px">
      <button class="tab ${drugsSelected ? 'selected' : ''}" onclick="setTreatmentTab('drugs')">Препараты · дозировки · курсы</button>
      <button class="tab ${drugsSelected ? '' : 'selected'}" onclick="setTreatmentTab('surgery')">Хирургическое лечение</button>
    </div>
    ${drugsSelected ? drugContent : surgeryContent}
  </div>`;
}

function setTreatmentTab(t){state.treatmentTab=t;render()}

function setStage(s){state.stage=s;render()}
function tnmPage(){return shell('TNM и FIGO',`<div class="notice">Краткий учебный ориентир, <b>не полная нормативная классификация</b>. Учитывайте неразмерные критерии T, cTNM/pTNM/ypTNM, гистологию и действующую редакцию. Автоматическое присвоение стадии отключено, чтобы не создавать ложной точности.</div><div class="panel"><label class="field">Локализация<select id="tnmSelect" onchange="renderTNM()">${tnm.map((x,i)=>`<option value="${i}">${esc(x.n)}</option>`).join('')}</select></label><div id="tnmDetail"></div></div><div class="sources"><a href="https://www.uicc.org/resources/tnm" target="_blank">UICC</a> · <a href="https://www.figo.org/" target="_blank">FIGO</a></div>`)}
function renderTNM(){const t=tnm[Number($('#tnmSelect').value)];$('#tnmDetail').innerHTML=`<p class="fine">${esc(t.v)}</p><p><b>T:</b> ${esc(t.t)}</p><p><b>N:</b> ${esc(t.ncat)}</p><p><b>M / стадия:</b> ${esc(t.m)}</p>`}
function calcPage(){return shell('Калькуляторы',`<div class="notice">Расчёты выполняются локально в браузере, не отправляются на сервер. Это арифметические инструменты, а не автоматические назначения. Вводите обезличенные параметры.</div>
<div class="calc-grid">
${calcBox('Площадь поверхности тела (Mosteller)','bsa',[['h','Рост, см','170'],['w','Масса, кг','70']],'BSA = √(рост × масса / 3600).')}
${calcBox('Карбоплатин (Calvert)','cal',[['auc','Целевая AUC','5'],['gfr','GFR, мл/мин (абсолютная)','75']],'Доза = AUC × (GFR + 25). GFR должна быть подходящей для формулы; не подставлять индексированную eGFR без пересчёта.')}
${calcBox('Cockcroft–Gault','cg',[['age','Возраст, лет','60'],['mass','Масса, кг','70'],['scr','Креатинин, мкмоль/л','90']],'Расчёт приблизительного CrCl; масса тела выбирается по клиническому протоколу.',[['sex','Пол','Мужской','Женский']])}
${calcBox('Индекс массы тела','bmi',[['bh','Рост, см','170'],['bw','Масса, кг','70']],'ИМТ = кг / м².')}
${calcBox('Абсолютное число нейтрофилов','anc',[['wbc','Лейкоциты, ×10⁹/л','4.2'],['neu','Нейтрофилы, %','55'],['bands','Палочкоядерные, % (если отдельно)','0']],'ANC = WBC × (% нейтрофилов + % палочкоядерных)/100. Не прибавлять палочкоядерные дважды.')}
${calcBox('Скорректированный кальций','ca',[['cat','Общий кальций, ммоль/л','2.1'],['alb','Альбумин, г/л','32']],'Ca скорр. = Ca + 0,02 × (40 − альбумин). При тяжёлых состояниях предпочтителен ионизированный кальций.')}
${calcBox('QTc по Fridericia','qtc',[['qt','QT, мс','380'],['rr','RR, мс','850']],'QTcF = QT / ∛(RR в секундах). Оценивать с ЭКГ и клиническим контекстом.')}
${calcBox('RECIST 1.1 — ориентир','recist',[['base','Сумма таргетных очагов исходно, мм','100'],['nadir','Минимальная сумма за наблюдение, мм','100'],['current','Текущая сумма, мм','65']],'PR: снижение ≥30% от исходной; PD: рост ≥20% от надира и ≥5 мм абсолютного прироста. Новые очаги и нетаргетные изменения оцениваются отдельно.',[['newlesion','Новые очаги','Нет','Есть']])}
</div>`)}
function calcBox(title,id,fields,note,selects=[]){return `<div class="panel"><h2>${title}</h2>${fields.map(([k,label,ph])=>`<label class="field">${label}<input type="number" step="any" data-calc="${id}" id="${id}_${k}" placeholder="${ph}" oninput="calculate('${id}')"></label>`).join('')}${selects.map(([k,label,...opts])=>`<label class="field">${label}<select id="${id}_${k}" onchange="calculate('${id}')">${opts.map((v,i)=>`<option value="${i}">${v}</option>`).join('')}</select></label>`).join('')}<div class="result" id="res_${id}">Введите значения</div><p class="fine">${note}</p></div>`}
function calculate(id){const v=k=>{let s=$(`#${id}_${k}`)?.value;return s===''||s==null?NaN:Number(s)};const valid=(...a)=>a.every(x=>Number.isFinite(x)&&x>=0);let out='Проверьте введённые значения';const f=(x,d=2)=>x.toLocaleString('ru-RU',{maximumFractionDigits:d,minimumFractionDigits:d});if(id==='bsa'&&valid(v('h'),v('w'))&&v('h')>0&&v('w')>0)out=f(Math.sqrt(v('h')*v('w')/3600),3)+' м²';if(id==='cal'&&valid(v('auc'),v('gfr'))&&v('auc')>0&&v('gfr')>0&&v('gfr')<=250)out=f(v('auc')*(v('gfr')+25),0)+' мг (расчёт, не назначение)';if(id==='cg'&&valid(v('age'),v('mass'),v('scr'))&&v('age')>=18&&v('age')<=120&&v('scr')>0&&v('mass')>0){let x=(140-v('age'))*v('mass')/(72*(v('scr')/88.4));if(v('sex')===1)x*=.85;out=f(x,1)+' мл/мин (приблизительно)'}if(id==='bmi'&&valid(v('bh'),v('bw'))&&v('bh')>0&&v('bw')>0)out=f(v('bw')/((v('bh')/100)**2),1)+' кг/м²';if(id==='anc'&&valid(v('wbc'),v('neu'),v('bands'))&&v('neu')+v('bands')<=100)out=f(v('wbc')*(v('neu')+v('bands'))/100,2)+' ×10⁹/л';if(id==='ca'&&valid(v('cat'),v('alb')))out=f(v('cat')+.02*(40-v('alb')),2)+' ммоль/л';if(id==='qtc'&&valid(v('qt'),v('rr'))&&v('rr')>0)out=f(v('qt')/Math.cbrt(v('rr')/1000),0)+' мс';if(id==='recist'&&valid(v('base'),v('nadir'),v('current'))&&v('base')>0&&v('nadir')>0){let p=(v('current')-v('base'))/v('base')*100,dp=(v('current')-v('nadir'))/v('nadir')*100;out=v('newlesion')===1?'Подозрение на PD: новый очаг':dp>=20&&v('current')-v('nadir')>=5?'Размерные критерии PD':p<=-30?'Размерные критерии PR':'Размерные критерии SD (если нет иных признаков PD/CR)';out+=` · Δ исходно ${f(p,1)}%`};$(`#res_${id}`).textContent=out}
function scales(){return shell('Клинические шкалы',`<div class="panel"><h2>ECOG Performance Status</h2>${['0 — Полностью активен','1 — Ограничена тяжёлая активность; лёгкая работа сохранена','2 — Самообслуживание сохранено, не способен работать; активен >50% дня','3 — Ограниченное самообслуживание; в постели/кресле >50% дня','4 — Полностью обездвижен, самообслуживание невозможно','5 — Смерть'].map(s=>`<p class="scale-row">${s}</p>`).join('')}</div>
<div class="panel"><h2>Karnofsky (KPS)</h2><p>100 — без жалоб; 90 — обычная активность, минимальные симптомы; 80 — обычная активность с усилием; 70 — обслуживает себя, не способен к обычной работе; 60 — нужна периодическая помощь; 50 — значительная помощь; 40 — инвалидизирован; 30 — госпитализация показана; 20 — тяжёлое состояние; 10 — терминальное состояние; 0 — смерть.</p></div>
<div class="panel"><h2>Khorana — риск ВТЭО при ХТ</h2><label class="field">Локализация<select id="kh_site" onchange="khorana()"><option value="0">Другие</option><option value="1">Лёгкое, лимфома, гинекологическая, мочевой пузырь, яичко</option><option value="2">Желудок или поджелудочная железа</option></select></label>${[['kh_pl','Тромбоциты ≥350 ×10⁹/л'],['kh_hb','Hb <100 г/л или ЭПО'],['kh_wbc','Лейкоциты >11 ×10⁹/л'],['kh_bmi','ИМТ ≥35 кг/м²']].map(([id,label])=>`<label class="check"><input id="${id}" type="checkbox" onchange="khorana()"> ${label}</label>`).join('')}<div class="result" id="kh_result">0 баллов — низкий риск</div><p class="fine">Шкала не заменяет оценку риска кровотечения и показаний к тромбопрофилактике.</p></div>
<div class="panel"><h2>Child–Pugh</h2>${[['cp_bili','Билирубин, мкмоль/л',['<34','34–50','>50']],['cp_alb','Альбумин, г/л',['>35','28–35','<28']],['cp_inr','INR',['<1,7','1,7–2,3','>2,3']],['cp_asc','Асцит',['Нет','Лёгкий/контролируемый','Выраженный/рефрактерный']],['cp_enc','Энцефалопатия',['Нет','I–II','III–IV']]].map(([id,label,opts])=>`<label class="field">${label}<select id="${id}" onchange="child()">${opts.map((o,i)=>`<option value="${i+1}">${o}</option>`).join('')}</select></label>`).join('')}<div class="result" id="cp_result">5 баллов — класс A</div><p class="fine">Клинические категории асцита и энцефалопатии требуют врачебной оценки.</p></div>
<div class="panel"><h2>IMDC — метастатический рак почки</h2>${[['im_time','Время от диагноза до системной терапии <1 года'],['im_kps','Karnofsky <80%'],['im_hb','Hb ниже нижней границы нормы'],['im_ca','Скорректированный Ca выше верхней границы нормы'],['im_neu','Нейтрофилы выше верхней границы нормы'],['im_pl','Тромбоциты выше верхней границы нормы']].map(([id,label])=>`<label class="check"><input id="${id}" type="checkbox" onchange="imdc()"> ${label}</label>`).join('')}<div class="result" id="im_result">0 факторов — благоприятный риск</div></div>
<div class="panel"><h2>Другие шкалы</h2><p><b>CTCAE:</b> степени 1–5 зависят от конкретного нежелательного явления; универсальной формулы нет. <b>MASCC:</b> требует полного набора клинических признаков и валидации; автоматический подсчёт пока не активирован. <b>R-ISS:</b> необходимы β2-микроглобулин, альбумин, ЛДГ и FISH; применяйте оригинальные критерии.</p></div>`)}
function khorana(){let n=Number($('#kh_site').value)+['kh_pl','kh_hb','kh_wbc','kh_bmi'].filter(x=>$('#'+x).checked).length;$('#kh_result').textContent=n+' балл(ов) — '+(n===0?'низкий':n<=2?'промежуточный':'высокий')+' риск (исходная классификация)'}
function child(){let n=['cp_bili','cp_alb','cp_inr','cp_asc','cp_enc'].reduce((a,x)=>a+Number($('#'+x).value),0);$('#cp_result').textContent=n+' баллов — Child–Pugh '+(n<=6?'A':n<=9?'B':'C')}
function imdc(){let n=['im_time','im_kps','im_hb','im_ca','im_neu','im_pl'].filter(x=>$('#'+x).checked).length;$('#im_result').textContent=n+' факторов — '+(n===0?'благоприятный':n<=2?'промежуточный':'неблагоприятный')+' риск'}
function markers(){return shell('Онкомаркеры',`<div class="notice">Онкомаркер не равен скрининговому тесту. Повышение требует клинической интерпретации; динамика не заменяет визуализацию или морфологию.</div><input class="search" placeholder="Найти опухоль или маркер…" oninput="filterMarkers(this.value)"><div id="markerList">${DATA.map(c=>markerRow(c)).join('')}</div>`)}
function markerRow(c){return `<div class="panel marker"><h3>${esc(c.title)}</h3><p>${esc(c.markers)}</p><button class="linkbtn" onclick="view('card','${c.id}')">Открыть карточку →</button></div>`}
function filterMarkers(q){$('#markerList').innerHTML=DATA.filter(c=>(c.title+' '+c.markers).toLowerCase().includes(q.toLowerCase())).map(markerRow).join('')}
function favorites(){let cs=DATA.filter(c=>favs().includes(c.id));return shell('Избранное',cs.length?cs.map(c=>`<button class="item" onclick="view('card','${c.id}')"><span><strong>${esc(c.title)}</strong><small>${esc(c.group)}</small></span>→</button>`).join(''):'<div class="panel muted">Пока нет избранных карточек.</div>')}
function about(){return shell('О проекте',`<div class="panel"><h2>ОнкоАтлас</h2><p>Бесплатный русскоязычный образовательный справочник для врачей. Все материалы открыты без регистрации.</p><p><b>Редакция:</b> 0.2 · 21 ноября 2026 года. <b>Статус:</b> рабочая бета-версия; клиническая экспертиза ещё не завершена.</p><p>Тексты карточек — сокращённые алгоритмы, не официальные рекомендации. Локальная регистрация лекарств и стандарты лечения различаются по странам.</p><p>Источники для редакционной проверки: ${sources.map(([n,u])=>`<a href="${u}" target="_blank">${n}</a>`).join(', ')}.</p><p><b>Конфиденциальность:</b> не вводите персональные данные пациентов. Калькуляторы выполняются в браузере. Избранное хранится локально.</p></div>`)}
function admin(){return shell('Администрирование',`<div class="panel"><h2>Публичный сайт — только чтение</h2><p>Защищённое редактирование ещё не подключено. Пароли в исходном коде отсутствуют. Вход «Икбал Р.В.» не будет реализован как небезопасная клиентская проверка.</p><p>Пока обновления выполняются заменой файлов после медицинской проверки. Для редактирования через чат потребуется подключение к репозиторию с ограниченными правами и подтверждением публикации.</p></div>`)}
function render(){const pages={home,catalog,card,tnm:tnmPage,calculators:calcPage,scales,markers,favorites,about,admin};$('#app').innerHTML=(pages[state.page]||home)();$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===state.page));if(state.page==='catalog')listCards();if(state.page==='tnm')renderTNM()}
window.view=view;window.toggleFav=toggleFav;window.setStage=setStage;window.searchHome=searchHome;window.listCards=listCards;window.renderTNM=renderTNM;window.calculate=calculate;window.khorana=khorana;window.child=child;window.imdc=imdc;window.filterMarkers=filterMarkers;
start();
